plus the Sunday release (new news, letters and a memo) once you have downloaded it."""

import csv
import json
import os
import sqlite3
from functools import cached_property
from pathlib import Path

MAX_ROWS = 200
RELEASE = "release-sunday"


class DataPackage:
    def __init__(self, root, release=None):
        """`root`: the unpacked package. `release`: the unpacked Sunday release (default: a
        `release-sunday` folder inside or next to the package, or ARENA_RELEASE), if present."""
        self.root = Path(root).expanduser().resolve()
        # facts.json holds every citable fact with the fields the arena checks claims against.
        own = self.root / "facts.json"
        facts = [own] if own.is_file() else [p for p in sorted(self.root.rglob("facts.json")) if RELEASE not in p.parts]
        self.facts = json.loads(facts[0].read_text(encoding="utf-8")) if facts else {}
        release = release or os.environ.get("ARENA_RELEASE")
        candidates = [Path(release).expanduser()] if release else [self.root / RELEASE, self.root.parent / RELEASE]
        self.release = next((p.resolve() for p in candidates if (p / "facts.json").is_file()), None)
        if self.release:  # new IDs only: nothing in the package changes
            self.facts |= json.loads((self.release / "facts.json").read_text(encoding="utf-8"))
        dbs = sorted(self.root.rglob("*.sqlite")) + sorted(self.root.rglob("*.db"))
        if not dbs and not facts:
            raise FileNotFoundError(f"no facts.json or .sqlite under {self.root}")
        self.db = None
        if dbs:
            self.db = sqlite3.connect(f"file:{dbs[0]}?mode=ro", uri=True, check_same_thread=False)
            self.db.row_factory = sqlite3.Row
            self.db.execute("PRAGMA query_only = ON")

    def tables(self):
        """{table: {"columns": [...], "rows": n}}"""
        if self.db is None:
            return {}
        names = [r[0] for r in self.db.execute("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name")]
        return {
            t: {
                "columns": [f"{c[1]} {c[2]}".strip() for c in self.db.execute(f'PRAGMA table_info("{t}")')],
                "rows": self.db.execute(f'SELECT count(*) FROM "{t}"').fetchone()[0],
            }
            for t in names
        }

    def query(self, sql, params=(), limit=MAX_ROWS):
        if self.db is None:
            raise ValueError("this package has no SQLite file")
        if sql.lstrip().split(None, 1)[0].lower() not in {"select", "with"}:
            raise ValueError("read-only: SELECT or WITH statements only")
        cur = self.db.execute(sql, params)
        return [dict(r) for r in cur.fetchmany(limit)]

    @cached_property
    def _ids(self):
        # A table's citable ID sits in its `id` column, else in its first column.
        index = {}
        for t, meta in self.tables().items():
            cols = [c.split()[0] for c in meta["columns"]]
            key = "id" if "id" in cols else cols[0]
            for row in self.db.execute(f'SELECT * FROM "{t}"'):
                value = row[key]
                if isinstance(value, str) and ":" in value:
                    index[value] = {"table": t, **dict(row)}
        for path in sorted(self.release.glob("data/*.csv")) if self.release else []:  # not in the SQLite
            with path.open(encoding="utf-8", newline="") as f:
                for row in csv.DictReader(f):
                    index[row["id"]] = {"table": path.stem, **row, "root": str(self.release)}
        return index

    def lookup(self, ref):
        """The fact behind a citable ID (from facts.json, else its table row), or None."""
        return self.facts.get(ref) or self._ids.get(ref)

    def ids(self, prefix):
        """All citable IDs starting with `prefix`, sorted, e.g. ids("idx:GP19-245113@")."""
        return sorted(i for i in self.facts.keys() | self._ids.keys() if i.startswith(prefix))

    def document(self, ref):
        """A document's text by ID (row with a path or body column) or by path in the package."""
        row, base = self._ids.get(ref) or self.facts.get(ref), self.root
        if row:
            for col in ("body", "text", "content"):
                if row.get(col):
                    return row[col]
            base = Path(row.get("root") or self.root)
            ref = next((row[c] for c in ("path", "file") if row.get(c)), None)
            if ref is None:
                return json.dumps(row, ensure_ascii=False)
        path = (base / ref).resolve()
        if not path.is_relative_to(base) or not path.is_file():
            raise FileNotFoundError(ref)
        return path.read_text(encoding="utf-8")

    @cached_property
    def cases(self):
        """Practice (and demo) case files in the package: {case_id: case}."""
        out = {}
        for p in sorted(self.root.rglob("cases/**/*.json")):
            case = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(case, dict) and "case_id" in case:
                out[case["case_id"]] = case
        return out
"""Bounded, schema-driven trades. History is authoritative across restarts."""

import itertools
import math
import time

from arena_kit.cost import complete_offer, must_haves_ok, total_cost
from arena_kit.play import moves_left

from .dossiers import build_one, load_package
from .evaluator import eligible_sheets, nonprice, price_for_cost
from .optimizer import best_terms


def packages(case, price, standard, supplier=None):
    fields = [f for f in case["negotiable"] if f != "unit_price" and case.get("term_options", {}).get(f)]
    base = complete_offer(case, {"unit_price": price})
    out = []
    for values in itertools.product(*(case["term_options"][f] for f in fields)):
        t = {**base, **dict(zip(fields, values, strict=True))}
        if must_haves_ok(case, t, standard):
            out.append((total_cost(case, t, standard, supplier), t))
    return sorted(out, key=lambda x: x[0])


def history(case, events):
    ours = [m["term_sheets"][0]["terms"] for m in events if m.get("from") == "buyer" and m.get("term_sheets")]
    keys = [nonprice(case, t) for t in ours]
    switches = sum(a != b for a, b in zip(keys, keys[1:], strict=False))
    return ours, keys, switches


class TradePolicy:
    def __init__(self, config, log):
        self.config, self.log = config, log
        self.traits = {}
        self.deadlines = {}

    def prepare(self, case):
        """Precompute dossiers before opening a session where the runner has case metadata."""
        for sid in case.get("suppliers", []):
            if sid in self.traits:
                continue
            try:
                d = build_one(load_package(), sid)
                self.traits[sid] = set(d.traits) if d else set()
            except (OSError, ValueError, KeyError, TypeError):
                self.traits[sid] = set()

    def initial(self, case, sid, price, anchor, standard, supplier, reference=None):
        self.prepare(case)
        preference = self.config.preferences.get(case["type"], self.config.preference)
        candidates = packages(case, price * (1 - anchor), standard, supplier)
        # Record both price surfaces; do not confuse buyer value with supplier willingness.
        self.log(
            case, "package_candidates", sid, at_quote=packages(case, price, standard, supplier), at_proposed=candidates
        )
        t = dict(candidates[0][1]) if candidates else best_terms(case, price, standard, supplier)
        options = case.get("term_options", {})
        if "multi_year_only" in self.traits[sid] and "contract_months" in t:
            tenors = [m for m in options.get("contract_months", []) if m >= 12 * case["buyer"]["horizon_years"]]
            if tenors:
                t["contract_months"] = max(tenors) if preference == "longer_tenor" else min(tenors)
            if "volume_per_year" in t and (reference or {}).get("volume_per_year") is not None:
                t["volume_per_year"] = reference["volume_per_year"]
        if "ppm_commitment" in t:
            # Relax only if the buyer's formula values the package equally and the must-have holds.
            for ppm in sorted(options.get("ppm_commitment", []), reverse=True):
                trial = {**t, "ppm_commitment": ppm}
                if must_haves_ok(case, trial, standard) and total_cost(case, trial, standard, supplier) <= total_cost(
                    case, t, standard, supplier
                ):
                    t = trial
                    break
        if preference == "standard_payment" and "payment_days" in t:
            if standard.get("payment_days") in options.get("payment_days", []):
                t["payment_days"] = standard["payment_days"]
        if preference == "lower_chargeback" and "chargeback_eur_per_complaint" in t:
            lower = [
                x for x in options.get("chargeback_eur_per_complaint", []) if x < t["chargeback_eur_per_complaint"]
            ]
            if lower:
                t["chargeback_eur_per_complaint"] = sorted(lower, reverse=True)[
                    min(self.config.chargeback_steps, len(lower)) - 1
                ]
                t["ppm_commitment"] = min(options["ppm_commitment"])
        return nonprice(case, t)

    def switch(self, case, sid, events, terms, standard, supplier):
        ours, tried, switches = history(case, events)
        if switches >= 2 or moves_left(case, events) < 3 or self.deadlines.get(sid, 0) - time.time() < 20:
            return terms, None
        replies = []
        for i, m in enumerate(events):
            if m.get("from") != "buyer" and m.get("term_sheets"):
                sheets = eligible_sheets(case, events[: i + 1], supplier, alternatives=True)
                if sheets:
                    replies.append(sheets[0][0])
        if len(replies) < 3 or replies[-1] < replies[-2] - 0.01 or replies[-2] < replies[-3] - 0.01:
            return terms, None
        options = case.get("term_options", {})
        # Only explore dimensions with a concrete case/supplier signal.
        fields = []
        text = " ".join(m.get("body", "") for m in events if m.get("from") != "buyer").lower()
        if "payment_days" in terms and (
            "wants_fast_payment" in self.traits.get(sid, set()) or "faster payment" in text or "shorter payment" in text
        ):
            fields.append("payment_days")
        if "contract_months" in terms:
            fields.append("contract_months")
        if "ppm_commitment" in terms:
            fields += ["chargeback_eur_per_complaint", "ppm_commitment"]
        if "index_clause" in terms:
            fields.append("index_clause")
        target = total_cost(case, terms, standard, supplier)
        for field in fields:
            values = list(options.get(field, []))
            if field == "payment_days":
                values = sorted((x for x in values if x < terms[field]), reverse=True)
            if field in ("contract_months", "ppm_commitment"):
                values = sorted(x for x in values if x > terms[field])
            if field == "chargeback_eur_per_complaint":
                values = sorted((x for x in values if x < terms[field]), reverse=True)
            for v in values:
                trial = {**terms, field: v}
                if v == terms.get(field) or nonprice(case, trial) in tried or not must_haves_ok(case, trial, standard):
                    continue
                if supplier:
                    continue  # inverse-price search is not monotonic with relationship estimates
                trial["unit_price"] = math.floor(price_for_cost(case, trial, target, standard) * 100) / 100
                if trial["unit_price"] <= 0 or total_cost(case, trial, standard) > target + 0.01:
                    continue
                self.log(
                    case,
                    "package_trade",
                    sid,
                    previous=terms,
                    selected=trial,
                    target_c=target,
                    selected_c=total_cost(case, trial, standard),
                    switches=switches + 1,
                )
                return complete_offer(case, trial), f"conditional trade: {field}"
        return terms, None
def _verb(x: float) -> str:
    return "rose" if x > 0 else "fell" if x < 0 else "moved"


def latest_window(values: dict[str, float], months: int = WINDOW_MONTHS) -> tuple[str, str] | None:
    """(start, end): end = the series' last month, start = `months` earlier; None if missing."""
    if not values:
        return None
    end = max(values)
    start = _month(_months(end) - months)
    return (start, end) if start in values else None


def best_buyer_window(values: dict[str, float]) -> tuple[str, str] | None:
    """The allowed window (≤ 12 months, ending within the last 12 months) with the largest fall."""
    if not values:
        return None
    last = _months(max(values))
    best, best_pct = None, 0.0
    for end in values:
        e = _months(end)
        if e < last - (WINDOW_MONTHS - 1):
            continue
        for k in range(1, WINDOW_MONTHS + 1):
            start = _month(e - k)
            if start in values and (p := _pct(values[start], values[end])) < best_pct:
                best, best_pct = (start, end), p
    return best


